get_product_page.code:
final response = await client.productPage.getProductPage();
final productPage = (response.map as Map)['product_page'] as Map;
print(productPage['configuration']);
print(productPage['quick_view']);

patch_product_page.code:
final response = await client.productPage.patchProductPage({
  'product_page': {
    'configuration': {
      'details': {'display_description': true},
    },
    'up_sell': {'short_description': true},
  },
});
final productPage = (response.map as Map)['product_page'] as Map;
print((productPage['configuration'] as Map)['details']);
print((productPage['up_sell'] as Map)['short_description']);

